import{c as d,Q as o,j as r,m as t}from"./chunks/framework.t4rEqR7d.js";const p=JSON.parse('{"title":"重命名 turn_id → run_id（或 round_id）","description":"","frontmatter":{},"headers":[],"relativePath":"plans/rename-turn-id.md","filePath":"plans/rename-turn-id.md"}'),n={name:"plans/rename-turn-id.md"};function a(i,e,c,l,u,s){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="重命名-turn-id-→-run-id-或-round-id" tabindex="-1">重命名 <code>turn_id</code> → <code>run_id</code>（或 <code>round_id</code>） <a class="header-anchor" href="#重命名-turn-id-→-run-id-或-round-id" aria-label="Permalink to &quot;重命名 `turn_id` → `run_id`（或 `round_id`）&quot;">​</a></h1><blockquote><p>状态：TODO（设计债，尚未实现） 记录：2026-07</p></blockquote><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>pagentv4 里 <strong>「turn」一词被用了两次</strong>，容易和 loop 内的 <code>turn</code>（<code>TurnBegin</code> / <code>TurnEnd</code>）混淆：</p><table tabindex="0"><thead><tr><th>符号</th><th>实际含义</th></tr></thead><tbody><tr><td>loop <code>turn</code>（0, 1, 2…）</td><td>一次 <code>runner.run()</code> <strong>内部</strong>的 LLM 调用序号</td></tr><tr><td><code>Message.turn_id</code></td><td><strong>第几条 user 消息</strong>；一次 <code>runner.run()</code> 内所有消息共享同一 id</td></tr></tbody></table><p><code>turn_id</code> 在语义上更接近 <strong>一次 run</strong>（<code>runner.run(user_input)</code>），而不是 loop turn。</p><p>赋值见 <code>src/pagentv4/runtime/loop_adapter.py</code>：<code>turn_id = messages.max_turn_id() + 1</code>，随每次 <code>run()</code> 递增。</p><h2 id="建议方向" tabindex="-1">建议方向 <a class="header-anchor" href="#建议方向" aria-label="Permalink to &quot;建议方向&quot;">​</a></h2><p>优先考虑 <strong><code>run_id</code></strong>（与 <code>RunBegin</code> / <code>RunEnd</code> 对齐），或 <strong><code>round_id</code></strong>（强调用户对话轮次）。</p><ul><li><code>system</code> 消息可继续用 <code>run_id=0</code>（或保留特例）。</li><li>loop 内序号继续叫 <strong><code>turn</code></strong>，不改。</li></ul><h2 id="影响面-改名时需扫" tabindex="-1">影响面（改名时需扫） <a class="header-anchor" href="#影响面-改名时需扫" aria-label="Permalink to &quot;影响面（改名时需扫）&quot;">​</a></h2><ul><li><code>Message.turn_id</code>、<code>Messages.max_turn_id()</code></li><li><code>RunState.turn_id</code></li><li><code>append_message</code> / <code>loop_adapter.run</code></li><li>JSONL / SQLite conversation 持久化字段</li><li><code>trace/view.py</code> 分组与 UI 标签</li><li><code>docs/pagentv4/core-types.md</code> 术语表</li><li>测试与 examples</li></ul><h2 id="迁移策略-待定" tabindex="-1">迁移策略（待定） <a class="header-anchor" href="#迁移策略-待定" aria-label="Permalink to &quot;迁移策略（待定）&quot;">​</a></h2><ol><li>新增字段 + 读写双兼容一段时间；或</li><li>一次性 breaking rename + JSONL 迁移脚本。</li></ol><h2 id="非目标" tabindex="-1">非目标 <a class="header-anchor" href="#非目标" aria-label="Permalink to &quot;非目标&quot;">​</a></h2><ul><li>不把 <code>run_id</code> 做成全局 UUID（保持 thread 内递增整数即可）。</li><li>不改动 loop <code>turn</code> / <code>TurnResult</code> / <code>TurnEnd</code> 命名。</li></ul>',16)])])}const h=d(n,[["render",a]]);export{p as __pageData,h as default};
